# Anti-diagonal reflection (across the line from top-right to bottom-left of 4x4)
# Let's divide into 4x4 quadrants

def transform_grid(grid, transform_name, transform_func):
    rows = len(grid)
    cols = len(grid[0])
    result = [[0]*cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            nr, nc = transform_func(r, c)
            # Handle wrap-around or out-of-bounds
            rows_new, cols_new = len(grid), len(grid[0])
            result[nr % rows_new][nc % cols_new] = grid[r][c]
    return result

